  1 | import fs from "node:fs";
  2 | import path from "node:path";
  3 | import express from "express";
  4 | import type { NextFunction, Request, Response } from "express";
  5 | import { isSlug, listAssignments, loadAssignment } from "./assignments";
  6 | import { nextHint, startSession } from "./agent";
  7 | import { HEARTBEAT_MS } from "./config";
  8 | import { runAssignment } from "./runner";
  9 | import {
 10 |   addClient,
 11 |   createSession,
 12 |   emitEvent,
 13 |   getSession,
 14 |   removeClient,
 15 |   setStatus,
 16 | } from "./sessions";
 17 | import { openSse, writeSseComment } from "./sse";
 18 | import type { Assignment } from "./types";
 19 | 
 20 | export function createApp(): express.Express {
 21 |   const app = express();
 22 |   app.use(express.json({ limit: "1mb" }));
 23 | 
 24 |   app.get("/api/health", (_req, res) => {
 25 |     res.json({ status: "ok" });
 26 |   });
 27 | 
 28 |   app.get("/api/assignments", (_req, res) => {
 29 |     const assignments = listAssignments();
 30 |     res.json(
 31 |       assignments.map((a) => ({
 32 |         id: a.id,
 33 |         language: a.language,
 34 |         statement: a.statement,
 35 |         starterCode: a.starterCode,
 36 |       })),
 37 |     );
 38 |   });
 39 | 
 40 |   app.post("/api/session", async (req: Request, res: Response, next: NextFunction) => {
 41 |     try {
 42 |       const body: unknown = req.body;
 43 |       if (typeof body !== "object" || body === null || Array.isArray(body)) {
 44 |         res.status(400).json({ error: "request body must be a JSON object" });
 45 |         return;
 46 |       }
 47 | 
 48 |       const assignmentId = (body as Record<string, unknown>).assignmentId;
 49 |       if (!isSlug(assignmentId)) {
 50 |         res.status(400).json({ error: "assignmentId is required and must be a plain slug" });
 51 |         return;
 52 |       }
 53 | 
 54 |       let assignment: Assignment;
 55 |       try {
 56 |         assignment = loadAssignment(assignmentId);
 57 |       } catch {
 58 |         res.status(404).json({ error: `unknown assignment: ${assignmentId}` });
 59 |         return;
 60 |       }
 61 | 
 62 |       const codeRaw = (body as Record<string, unknown>).code;
 63 |       let code: string;
 64 |       if (codeRaw === undefined || codeRaw === null || codeRaw === "") {
 65 |         code = assignment.starterCode;
 66 |       } else if (typeof codeRaw !== "string") {
 67 |         res.status(400).json({ error: "code must be a string" });
 68 |         return;
 69 |       } else {
 70 |         code = codeRaw;
 71 |       }
 72 | 
 73 |       // Run the runner WITHOUT cleanup so the temp workdir persists for the
 74 |       // agent. The workdir is the agent's sandbox and lives until the session
 75 |       // ends/TTL, at which point the session cleanup loop removes it.
 76 |       const testResults = await runAssignment(assignment, code, { cleanup: false });
 77 | 
 78 |       const session = createSession({
 79 |         assignmentId: assignment.id,
 80 |         language: assignment.language,
 81 |         statement: assignment.statement,
 82 |         workdir: testResults.sandboxDir,
 83 |         testResults,
 84 |       });
 85 | 
 86 |       // Record the test results first so they replay before any agent event.
 87 |       emitEvent(session, "test_results", testResults);
 88 |       setStatus(session, "running");
 89 | 
 90 |       // Fire-and-forget: ask the agent for a level-1 hint in the background.
 91 |       startSession(session.id).catch((err) => {
 92 |         emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
 93 |         setStatus(session, "error");
 94 |       });
 95 | 
 96 |       res.json({ sessionId: session.id, testResults });
 97 |     } catch (err) {
 98 |       next(err);
 99 |     }
100 |   });
101 | 
102 |   app.get("/api/session/:id/stream", (req: Request, res: Response) => {
103 |     const session = getSession(String(req.params.id));
104 |     if (!session) {
105 |       res.status(404).json({ error: "unknown session" });
106 |       return;
107 |     }
108 | 
109 |     openSse(res);
110 |     res.write(": connected\n\n");
111 |     addClient(session, res); // replays buffered events + registers for live events
112 | 
113 |     const heartbeat = setInterval(() => {
114 |       try {
115 |         writeSseComment(res, "ping");
116 |       } catch {
117 |         /* ignore */
118 |       }
119 |     }, HEARTBEAT_MS);
120 |     heartbeat.unref();
121 | 
122 |     res.on("close", () => {
123 |       clearInterval(heartbeat);
124 |       removeClient(session, res);
125 |     });
126 |   });
127 | 
128 |   app.post("/api/session/:id/next-hint", async (req: Request, res: Response, next: NextFunction) => {
129 |     try {
130 |       const session = getSession(String(req.params.id));
131 |       if (!session) {
132 |         res.status(404).json({ error: "unknown session" });
133 |         return;
134 |       }
135 |       if (session.busy) {
136 |         res.status(409).json({ error: "agent is still busy", status: session.status });
137 |         return;
138 |       }
139 |       const result = await nextHint(session.id);
140 |       res.json(result);
141 |     } catch (err) {
142 |       const status = (err as { status?: number }).status;
143 |       if (status === 404) {
144 |         res.status(404).json({ error: "unknown session" });
145 |         return;
146 |       }
147 |       if (status === 409) {
148 |         res.status(409).json({ error: "agent is still busy" });
149 |         return;
150 |       }
151 |       next(err);
152 |     }
153 |   });
154 | 
155 |   const webDir = path.resolve(process.cwd(), "web");
156 |   if (fs.existsSync(webDir)) {
157 |     app.use(express.static(webDir));
158 |   }
159 | 
160 |   // eslint-disable-next-line @typescript-eslint/no-explicit-any
161 |   app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
162 |     const status = typeof err?.status === "number" ? err.status : 500;
163 |     if (status >= 400 && status < 500) {
164 |       res.status(status).json({ error: "invalid request body" });
165 |       return;
166 |     }
167 |     console.error(err);
168 |     res.status(500).json({ error: "internal server error" });
169 |   });
170 | 
171 |   return app;
172 | }

