259 | /** Lazily create the one shared ClineCore instance and subscribe once. */
260 | async function getCline(): Promise<ClineCore> {
261 |   if (!clineCorePromise) {
262 |     clineCorePromise = (async () => {
263 |       const cline = await ClineCore.create({ clientName: "hintlab", backendMode: "local" });
264 |       cline.subscribe((e: unknown) => handleCoreEvent(e as Parameters<typeof handleCoreEvent>[0]));
265 |       return cline;
266 |     })();
267 |   }
268 |   return clineCorePromise;
269 | }
