271 | // Register the hook so session cleanup can stop the SDK session too.
272 | setStopAgentHook((agentSessionId) => {
273 |   if (!clineCorePromise) return;
274 |   clineCorePromise
275 |     .then((cline) => cline.stop(agentSessionId).catch(() => undefined))
276 |     .catch(() => undefined);
277 | });
