279 | function buildTestResultsText(session: Session): string {
280 |   const lines: string[] = [];
281 |   for (const t of session.testResults.tests) {
282 |     lines.push(
283 |       `- ${t.name}: input=${JSON.stringify(t.input)} expected=${JSON.stringify(t.expected)} got=${JSON.stringify(t.got)} ` +
284 |         `(passed=${t.passed})`,
285 |     );
286 |   }
287 |   if (session.testResults.build && !session.testResults.build.ok) {
288 |     lines.push(`(build failed: ${session.testResults.build.stderr.trim().slice(0, 400)})`);
289 |   }
290 |   return lines.join("\n");
291 | }
