293 | function buildFirstPrompt(session: Session, mainPath: string, testsPath: string): string {
294 |   return [
295 |     `The student is working on assignment "${session.assignmentId}" (${session.language}): ${session.statement}`,
296 |     "",
297 |     `Files (use these ABSOLUTE paths with read_files):`,
298 |     `- Student code: ${mainPath}`,
299 |     `- Tests: ${testsPath}`,
300 |     "",
301 |     "The program was already run against the test cases. Results:",
302 |     buildTestResultsText(session),
303 |     "",
304 |     "Diagnose the root cause of the failure(s). Read the files and run allow-listed commands",
305 |     "to confirm your diagnosis (run_commands already runs inside the workdir, so use relative",
306 |     "commands: python3 main.py / echo \"...\" | python3 main.py / cat main.py / cat tests.json,",
307 |     "or for C the gcc build and ./main — never `cd` or absolute paths). Then call the give_hint",
308 |     "tool EXACTLY ONCE with level 1 (a conceptual nudge). Do not write or show corrected code,",
309 |     "and do not call give_hint more than once.",
310 |   ].join("\n");
311 | }
