313 | function buildNextPrompt(_session: Session, level: number): string {
314 |   return [
315 |     "The student is still stuck and asked for the next hint.",
316 |     `Give the next hint at level ${level}`,
317 |     "(1 = conceptual nudge, 2 = where to look, 3 = near-explicit concept).",
318 |     `Call the give_hint tool EXACTLY ONCE with level ${level}. Do not write or show corrected code.`,
319 |   ].join("\n");
320 | }
