 3 | /** JSON.stringify that tolerates BigInt and non-serialisable values. */
 4 | function safeStringify(data: unknown): string {
 5 |   try {
 6 |     return JSON.stringify(data ?? null, (_key, value) =>
 7 |       typeof value === "bigint" ? value.toString() : value,
 8 |     );
 9 |   } catch {
10 |     return JSON.stringify(null);
11 |   }
12 | }
13 | 
14 | /** Open a Server-Sent Events stream on the response. */
15 | export function openSse(res: Response): void {
16 |   res.setHeader("Content-Type", "text/event-stream");
17 |   res.setHeader("Cache-Control", "no-cache");
18 |   res.setHeader("Connection", "keep-alive");
19 |   res.setHeader("X-Accel-Buffering", "no");
20 |   res.flushHeaders();
21 | }
22 | 
23 | /** Write a single named SSE event. */
24 | export function writeSse(res: Response, name: string, data: unknown): void {
25 |   if (res.writableEnded || res.destroyed) return;
26 |   res.write(`event: ${name}\ndata: ${safeStringify(data)}\n\n`);
27 | }
28 | 
29 | /** Write an SSE comment (used as a keep-alive heartbeat). */
30 | export function writeSseComment(res: Response, comment: string): void {
31 |   if (res.writableEnded || res.destroyed) return;
32 |   res.write(`: ${comment}\n\n`);
33 | }

 1 | /**
 2 |  * HintLab hint guard.
 3 |  *
 4 |  * Before a hint is stored or sent to the student, it is checked here. If it
 5 |  * contains a fenced code block, inline code that is more than a short
 6 |  * identifier/expression, multiple source-code-like lines, or anything that looks
 7 |  * like a rewritten solution, it is rejected (and give_hint returns an error so
 8 |  * the model rephrases without code).
 9 |  */
10 | 
11 | export interface HintCheck {
12 |   ok: boolean;
13 |   reason?: string;
14 | }
15 | 
16 | /** Builtins whose `name(` form is a strong signal of a code expression. */
17 | const CODE_FUNCTION_RE =
18 |   /\b(?:range|len|sum|print|printf|scanf|input|append|split|map|list|int|float|str|lower|replace|strip|reversed|enumerate|zip|sorted|min|max|open|read|write|fgets|gets|puts)\s*\(/;
19 | 
20 | /** A single line that looks like actual source code / a rewritten solution. */
21 | const CODE_LINE_PATTERNS: readonly RegExp[] = [
22 |   /^\s*(def|class|import|from|return|print|printf|scanf|#include|else|elif)\b/,
23 |   /^\s*(for|while|if)\s*\(/, // C control structures
24 |   /^\s*(for|while|if|elif|else)\b[^:]*:$/, // Python control structures ending in ":"
25 |   /\bfor\s+\w+\s+in\s/, // Python for ... in
26 |   CODE_FUNCTION_RE,
27 |   /[A-Za-z_]\w*\s*(?:=|\+=|-=|\*=|\/=|%=)\s*[^=]/, // assignment
28 |   /\b(?:int|float|double|char|void|long|short|unsigned)\s+\w+\s*[=;(\[]/, // C declaration
29 |   /(?:\(float\)|\(int\)|\(double\)|\(char\))/, // C casts (e.g. (float) sum / n)
30 |   /;\s*$/, // trailing semicolon (C statement)
31 |   /->/, // C struct/member dereference
32 | ];
33 | 
34 | function looksLikeCodeLine(line: string): boolean {
35 |   const s = line.trim();
36 |   if (!s) return false;
37 |   return CODE_LINE_PATTERNS.some((re) => re.test(s));
38 | }
39 | 
40 | /**
41 |  * Check a hint's text. Returns `{ ok: true }` when it is safe to show, otherwise
42 |  * `{ ok: false, reason }` describing what made it look like code.
43 |  */
44 | export function checkHint(text: string): HintCheck {
45 |   const t = text.trim();
46 |   if (!t) return { ok: false, reason: "empty hint" };
47 | 
48 |   // 1. Fenced code blocks.
49 |   if (t.includes("```")) {
50 |     return { ok: false, reason: "contains a fenced code block" };
51 |   }
52 | 
53 |   // 2. Inline code spans: allow only a short identifier/expression.
54 |   const inline = t.matchAll(/`([^`\n]+)`/g);
55 |   for (const m of inline) {
56 |     const code = m[1].trim();
57 |     if (code.length > 20) {
58 |       return { ok: false, reason: "inline code is longer than a short identifier/expression" };
59 |     }
60 |     // Reject inline code that is clearly an expression rather than a plain name.
61 |     if (/[(){}=<>;,]|->/.test(code)) {
62 |       return { ok: false, reason: "inline code looks like an expression" };
63 |     }
64 |   }
65 | 
66 |   // 3. Any line that looks like source code / a rewritten solution.
67 |   const lines = t.split("\n");
68 |   if (lines.some(looksLikeCodeLine)) {
69 |     return { ok: false, reason: "text looks like source code or a rewritten solution" };
70 |   }
71 | 
72 |   return { ok: true };
73 | }

  1 | /**
  2 |  * HintLab run_commands allow-list.
  3 |  *
  4 |  * `run_commands` executes on the HOST (inside the session workdir), so this
  5 |  * allow-list is the only thing standing between the model and an arbitrary
  6 |  * shell. It is deliberately strict and exported so scripts/check-agent.ts can
  7 |  * unit-test it.
  8 |  */
  9 | 
 10 | export interface AllowDecision {
 11 |   allowed: boolean;
 12 |   reason?: string;
 13 | }
 14 | 
 15 | /**
 16 |  * Substrings that are rejected on every command before the whitelist match runs.
 17 |  * This is defence-in-depth: even a command that happens to satisfy a structural
 18 |  * regex (for example the free-form payload of an `echo ... | python3 main.py`)
 19 |  * is still rejected if it smuggles shell metacharacters.
 20 |  */
 21 | export const DENY_SUBSTRINGS: readonly string[] = [
 22 |   ";", // command separator
 23 |   "&&", // and-list
 24 |   "||", // or-list
 25 |   "`", // command substitution
 26 |   "$(", // command substitution
 27 |   "${", // parameter expansion
 28 |   ">", // output redirection (writing files)
 29 |   "&", // backgrounding / single ampersand
 30 |   "\n", // literal newline = another command
 31 |   "\r", // literal carriage return
 32 |   "*", // glob expansion
 33 |   "?", // glob expansion
 34 | ];
 35 | 
 36 | /**
 37 |  * The whitelist. Each trimmed command must match exactly one of these anchored
 38 |  * patterns. Only the assignment's own build/run/read commands are allowed.
 39 |  */
 40 | export const ALLOWED_COMMANDS: readonly RegExp[] = [
 41 |   // --- Python: run the program ---
 42 |   /^python3 main\.py$/,
 43 |   // stdin redirect from a simple file name (no slashes → cannot escape the workdir)
 44 |   /^python3 main\.py < [A-Za-z0-9_.-]+$/,
 45 |   // pipe literal input into the program (echo/printf only; no nested pipes/redirects)
 46 |   /^(echo|printf) [^|<>]+ \| python3 main\.py$/,
 47 |   // --- C: build + run ---
 48 |   /^gcc -Wall -O0 main\.c -o main$/, // the exact tests.json build command
 49 |   /^\.\/main$/,
 50 |   /^\.\/main < [A-Za-z0-9_.-]+$/,
 51 |   /^(echo|printf) [^|<>]+ \| \.\/main$/,
 52 |   // --- Reads ---
 53 |   /^cat (main\.py|main\.c|tests\.json)$/,
 54 | ];
 55 | 
 56 | /**
 57 |  * Normalise the (loosely-typed) run_commands input into a flat list of command
 58 |  * strings. Handles both the simple `{ commands: string[] }` shape and the
 59 |  * structured `{ command, args }` / string forms the SDK accepts.
 60 |  */
 61 | export function extractCommands(input: unknown): string[] {
 62 |   if (input == null) return [];
 63 |   const obj = input as Record<string, unknown>;
 64 |   const raw: unknown = "commands" in obj ? obj.commands : input;
 65 | 
 66 |   if (Array.isArray(raw)) {
 67 |     return raw
 68 |       .map((c): string | undefined => {
 69 |         if (typeof c === "string") return c;
 70 |         if (c && typeof c === "object") return (c as Record<string, unknown>).command as string | undefined;
 71 |         return undefined;
 72 |       })
 73 |       .filter((c): c is string => typeof c === "string" && c.trim().length > 0);
 74 |   }
 75 | 
 76 |   if (typeof raw === "string") return [raw];
 77 |   if (raw && typeof raw === "object") {
 78 |     const c = (raw as Record<string, unknown>).command;
 79 |     if (typeof c === "string") return [c];
 80 |   }
 81 |   return [];
 82 | }
 83 | 
 84 | /** Decide whether a single (trimmed) command is allowed. */
 85 | export function allowCommand(command: string): AllowDecision {
 86 |   const cmd = command.trim();
 87 |   if (!cmd) return { allowed: false, reason: "empty command" };
 88 | 
 89 |   for (const sub of DENY_SUBSTRINGS) {
 90 |     if (cmd.includes(sub)) {
 91 |       return { allowed: false, reason: `forbidden token ${JSON.stringify(sub)}` };
 92 |     }
 93 |   }
 94 | 
 95 |   if (!ALLOWED_COMMANDS.some((re) => re.test(cmd))) {
 96 |     return { allowed: false, reason: "command not on the HintLab allow-list" };
 97 |   }
 98 | 
 99 |   return { allowed: true };
100 | }
101 | 
102 | /** Decide whether a list of commands is allowed (every command must be allowed). */
103 | export function allowCommands(commands: string[]): AllowDecision {
104 |   if (commands.length === 0) return { allowed: false, reason: "no commands provided" };
105 |   for (const c of commands) {
106 |     const d = allowCommand(c);
107 |     if (!d.allowed) return d;
108 |   }
109 |   return { allowed: true };
110 | }

