 24 | /**
 25 |  * Split a command string into argv without invoking a shell. Supports single/
 26 |  * double quotes and backslash escapes, but the fixtures only use simple,
 27 |  * whitespace-separated commands ("python3 main.py", "gcc -Wall -O0 main.c -o main", "./main").
 28 |  */
 29 | function tokenize(command: string): string[] {
 30 |   const tokens: string[] = [];
 31 |   let current = "";
 32 |   let quote: "'" | '"' | null = null;
 33 | 
 34 |   for (let i = 0; i < command.length; i++) {
 35 |     const ch = command[i];
 36 |     if (quote) {
 37 |       if (ch === quote) {
 38 |         quote = null;
 39 |       } else {
 40 |         current += ch;
 41 |       }
 42 |     } else if (ch === '"' || ch === "'") {
 43 |       quote = ch;
 44 |     } else if (ch === "\\" && i + 1 < command.length) {
 45 |       current += command[i + 1];
 46 |       i += 1;
 47 |     } else if (/\s/.test(ch)) {
 48 |       if (current) {
 49 |         tokens.push(current);
 50 |         current = "";
 51 |       }
 52 |     } else {
 53 |       current += ch;
 54 |     }
 55 |   }
 56 | 
 57 |   if (current) tokens.push(current);
 58 |   return tokens;
 59 | }
