 61 | /**
 62 |  * Minimal environment handed to the student program and the gcc build. Only
 63 |  * PATH (so python3/gcc are still found), HOME (pointed at the run's temp dir),
 64 |  * and LANG are set. The server's process.env is deliberately NOT inherited, so
 65 |  * ClinePass/SDK credentials or any other server env var can never leak into
 66 |  * student code.
 67 |  */
 68 | function minimalEnv(home: string): NodeJS.ProcessEnv {
 69 |   const pathEnv = process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin";
 70 |   return {
 71 |     PATH: pathEnv,
 72 |     HOME: home,
 73 |     LANG: "C.UTF-8",
 74 |   };
 75 | }
