 88 | export function loadAssignment(id: string): Assignment {
 89 |   if (!isSlug(id)) {
 90 |     throw new Error(`invalid assignment id: ${JSON.stringify(id)}`);
 91 |   }
 92 | 
 93 |   const dir = path.join(ASSIGNMENTS_DIR, id);
 94 |   const testsJsonPath = path.join(dir, "tests.json");
 95 |   if (!fs.existsSync(testsJsonPath)) {
 96 |     throw new Error(`unknown assignment: ${id}`);
 97 |   }
 98 | 
 99 |   let raw: unknown;
100 |   try {
101 |     raw = JSON.parse(fs.readFileSync(testsJsonPath, "utf8"));
102 |   } catch (err) {
103 |     throw new Error(`assignment ${id}: failed to parse tests.json: ${(err as Error).message}`);
104 |   }
105 | 
106 |   const assignment = validateAssignment(id, raw);
107 | 
108 |   const starterFile = assignment.language === "python" ? "main.py" : "main.c";
109 |   const starterPath = path.join(dir, starterFile);
110 |   if (!fs.existsSync(starterPath)) {
111 |     throw new Error(`assignment ${id}: missing starter file ${starterFile}`);
112 |   }
113 |   assignment.starterCode = fs.readFileSync(starterPath, "utf8");
114 | 
115 |   return assignment;
116 | }
117 | 
118 | export function listAssignments(): Assignment[] {
119 |   if (!fs.existsSync(ASSIGNMENTS_DIR)) return [];
120 | 
121 |   const entries = fs.readdirSync(ASSIGNMENTS_DIR, { withFileTypes: true });
122 |   const ids = entries
123 |     .filter(
124 |       (e) =>
125 |         e.isDirectory() &&
126 |         isSlug(e.name) &&
127 |         fs.existsSync(path.join(ASSIGNMENTS_DIR, e.name, "tests.json")),
128 |     )
129 |     .map((e) => e.name)
130 |     .sort();
131 | 
132 |   return ids.map((id) => loadAssignment(id));
133 | }

