 93 | /** PIDs whose command line matches the given `pgrep -f` pattern. */
 94 | function pidsMatching(pattern: string): string[] {
 95 |   try {
 96 |     return execFileSync("pgrep", ["-f", pattern], { encoding: "utf8" })
 97 |       .split("\n")
 98 |       .map((s) => s.trim())
 99 |       .filter(Boolean);
100 |   } catch {
101 |     return []; // pgrep exits non-zero when nothing matches
102 |   }
103 | }
104 | 
105 | /** Poll until no process matches the pattern (confirms the group was reaped). */
106 | async function waitUntilNoPids(pattern: string, timeoutMs = 3000): Promise<boolean> {
107 |   const deadline = Date.now() + timeoutMs;
108 |   while (Date.now() < deadline) {
109 |     if (pidsMatching(pattern).length === 0) return true;
110 |     await new Promise((r) => setTimeout(r, 100));
111 |   }
112 |   return pidsMatching(pattern).length === 0;
113 | }
