182 |           else if (name === "approval") approvals.push(data as { toolName?: string; commands?: string[]; allowed?: boolean; reason?: string });
183 |           else if (name === "tool_call") toolCalls.push(data as { toolName?: string });
184 |           else if (name === "status" && data && typeof (data as { status?: unknown }).status === "string") {
185 |             lastStatus = (data as { status: string }).status;
186 |           }
187 |         }
188 |       }
