322 | /** Run the first (level-1) agent turn in the background for a session. */
323 | export async function startSession(sessionId: string): Promise<void> {
324 |   const session = getSession(sessionId);
325 |   if (!session) return;
326 | 
327 |   const mainFile = session.language === "python" ? "main.py" : "main.c";
328 |   const mainPath = path.resolve(session.workdir, mainFile);
329 |   const testsPath = path.resolve(session.workdir, "tests.json");
330 | 
331 |   const cline = await getCline();
332 |   session.busy = true;
333 |   setStatus(session, "running");
334 | 
335 |   try {
336 |     const result = await cline.start({
337 |       interactive: true,
338 |       prompt: buildFirstPrompt(session, mainPath, testsPath),
339 |       config: {
340 |         sessionId: session.id,
341 |         providerId: HINTLAB_PROVIDER_ID,
342 |         modelId: HINTLAB_MODEL_ID,
343 |         temperature: 0,
344 |         systemPrompt: SYSTEM_PROMPT,
345 |         // session.workdir is the runner's temp sandbox dir, kept alive for the
346 |         // agent via runAssignment(..., { cleanup: false }) in app.ts. It is the
347 |         // agent's whole sandbox and is removed by the session cleanup loop when
348 |         // the session ends/TTL expires (see sessions.ts deleteSession).
349 |         cwd: session.workdir,
350 |         workspaceRoot: session.workdir,
351 |         enableTools: true,
352 |         enableSpawnAgent: false,
353 |         enableAgentTeams: false,
354 |         extraTools: [giveHintTool as unknown as AgentTool],
355 |       },
356 |       toolPolicies: toolPolicies(),
357 |       capabilities: capabilities(),
358 |     });
359 | 
360 |     session.agentSessionId = result.sessionId;
361 |     registerAgentSession(result.sessionId, session.id);
362 |     const finishReason = (result.result as { finishReason?: string } | undefined)?.finishReason;
363 |     emitEvent(session, "status", { message: "initial agent turn finished", finishReason });
364 |   } catch (err) {
365 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
366 |     setStatus(session, "error");
367 |   } finally {
368 |     session.busy = false;
369 |     if (session.status !== "error") {
370 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
371 |     }
372 |   }
373 | }
