375 | /** Ask the agent for the next hint level (2, then 3). Returns after the turn completes. */
376 | export async function nextHint(sessionId: string): Promise<{ level: number; status: string; message?: string }> {
377 |   const session = getSession(sessionId);
378 |   if (!session) throw Object.assign(new Error("unknown session"), { status: 404 });
379 |   if (session.busy) throw Object.assign(new Error("agent is still busy"), { status: 409 });
380 |   if (session.hints.length >= 3) {
381 |     return { level: 3, status: "complete", message: "All three hint levels have already been delivered." };
382 |   }
383 | 
384 |   const nextLevel = Math.min(session.hints.length + 1, 3);
385 |   session.currentHintLevel = nextLevel;
386 |   session.busy = true;
387 |   setStatus(session, "running");
388 | 
389 |   const cline = await getCline();
390 |   try {
391 |     const result = await cline.send({
392 |       sessionId: session.agentSessionId ?? session.id,
393 |       prompt: buildNextPrompt(session, nextLevel),
394 |     });
395 |     const finishReason = (result as { finishReason?: string } | undefined)?.finishReason;
396 |     emitEvent(session, "status", { message: `level ${nextLevel} agent turn finished`, finishReason });
397 |   } catch (err) {
398 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
399 |     setStatus(session, "error");
400 |   } finally {
401 |     session.busy = false;
402 |     if (session.status !== "error") {
403 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
404 |     }
405 |   }
406 | 
407 |   return { level: nextLevel, status: session.status };
408 | }
