201 |     // The hint is delivered *during* the turn; wait for the agent to finish that
202 |     // turn (busy=false) before asking for the next level.
203 |     await waitUntil(() => lastStatus === "idle" || lastStatus === "complete", "agent idle after level-1 hint", 120000);
204 | 
205 |     // Ask for level 2.
206 |     let nh = await fetch(`${BASE}/api/session/${sessionId}/next-hint`, { method: "POST" });
207 |     check(nh.status === 200, `next-hint (level 2) -> 200 (got ${nh.status})`);
208 |     console.log("next-hint (level 2) response:", await nh.clone().json());
209 |     await waitUntil(() => hints.some((h) => h.level === 2), "level-2 hint over SSE", 240000);
210 | 
211 |     // Ask for level 3.
212 |     nh = await fetch(`${BASE}/api/session/${sessionId}/next-hint`, { method: "POST" });
213 |     check(nh.status === 200, `next-hint (level 3) -> 200 (got ${nh.status})`);
214 |     console.log("next-hint (level 3) response:", await nh.clone().json());
215 |     await waitUntil(() => hints.some((h) => h.level === 3), "level-3 hint over SSE", 240000);
216 | 
217 |     // A fourth request should report "complete".
218 |     nh = await fetch(`${BASE}/api/session/${sessionId}/next-hint`, { method: "POST" });
219 |     const nh4 = (await nh.json()) as { status?: string; level?: number; message?: string };
220 |     check(nh4.status === "complete", `next-hint after level 3 -> complete (got ${JSON.stringify(nh4)})`);
221 |     console.log("next-hint (after level 3) response:", nh4);
222 |   } finally {
223 |     controller.abort();
224 |     await streamTask;
225 |   }
