import path from "node:path";
import { extractCommands } from "./allowlist";
import type { RunResult } from "./types";

/**
 * The server-side SSE filter.
 *
 * `GET /api/session/:id/stream` must NEVER leak unguarded model output to the
 * browser. This module defines an explicit allow-list of event types (and a
 * per-type sanitisation) that may reach a client. Every other event —
 * including `agent_text`, `reasoning`, and any tool payload that carries the
 * model's own free text — is dropped here.
 *
 * Raw events are still stored on the session (`session.events`) for
 * server-side logging/debugging; this filter only governs what is written to
 * an SSE client, for both live events and the replay of past events.
 */

export interface ClientEvent {
  name: string;
  data: unknown;
}

function asRecord(data: unknown): Record<string, unknown> | null {
  return typeof data === "object" && data !== null && !Array.isArray(data)
    ? (data as Record<string, unknown>)
    : null;
}

function stringField(data: unknown, key: string): string {
  const rec = asRecord(data);
  const v = rec?.[key];
  return typeof v === "string" ? v : "";
}

function toolNameOf(data: unknown): string {
  return stringField(data, "toolName");
}

/** Map a guard/level reason to a short, stable category (never the raw text). */
function reasonCategory(reason: string): string {
  if (reason === "wrong level") return "wrong level";
  if (reason === "empty hint" || reason === "empty") return "empty";
  if (/code|fenced|source|inline|expression|solution|backtick/i.test(reason)) {
    return "contained code";
  }
  return "blocked";
}

/** Turn a raw SDK/provider error into one short human line (no stack traces). */
function friendlyError(data: unknown): ClientEvent {
  const msg = stringField(data, "message").toLowerCase();
  let message: string;
  if (/(timeout|timed out|etimedout|abort)/.test(msg)) {
    message = "Tutor timed out, try again";
  } else if (/(rate|quota|429|overload|capacity|busy|too many)/.test(msg)) {
    message = "Tutor is busy, try again in a moment";
  } else if (/(auth|unauthorized|401|403|credential|key|token)/.test(msg)) {
    message = "Tutor is unavailable, check the server";
  } else {
    message = "Something went wrong, please try again";
  }
  return { name: "error", data: { message } };
}

function fileOf(input: unknown): string | undefined {
  const rec = asRecord(input);
  if (!rec) return undefined;
  const p = typeof rec.path === "string" ? rec.path : typeof rec.file === "string" ? rec.file : undefined;
  return p ? path.basename(p) : undefined;
}

/** tool_call: only run_commands / read_files / run_tests, with command or file name. */
function toolCall(data: unknown): ClientEvent | null {
  const name = toolNameOf(data);
  const input = asRecord(data)?.input;
  if (name === "run_commands") {
    const command = extractCommands(input);
    return { name: "tool_call", data: { toolName: "run_commands", command } };
  }
  if (name === "read_files") {
    return { name: "tool_call", data: { toolName: "read_files", file: fileOf(input) } };
  }
  if (name === "run_tests") {
    const test = asRecord(input)?.test;
    return { name: "tool_call", data: { toolName: "run_tests", test: typeof test === "string" ? test : undefined } };
  }
  // give_hint / search_codebase / anything else may carry model text — drop.
  return null;
}

function shortSummary(output: unknown): string {
  const s = typeof output === "string" ? output : JSON.stringify(output ?? "");
  const trimmed = s.replace(/\s+/g, " ").trim();
  return trimmed.length > 200 ? `${trimmed.slice(0, 200)}…` : trimmed;
}

/** tool_result: a short trimmed summary; never the model's own text. */
function toolResult(data: unknown): ClientEvent | null {
  const name = toolNameOf(data);
  const output = asRecord(data)?.output;
  if (name === "run_commands") {
    return { name: "tool_result", data: { toolName: "run_commands", summary: shortSummary(output) } };
  }
  if (name === "run_tests") {
    const o = asRecord(output);
    const total = typeof o?.total === "number" ? o.total : undefined;
    const passed = typeof o?.passed === "number" ? o.passed : undefined;
    const failed = typeof o?.failed === "number" ? o.failed : undefined;
    const summary = total === undefined ? "ran tests" : `${total} test(s), ${passed ?? 0} passed, ${failed ?? 0} failed`;
    return { name: "tool_result", data: { toolName: "run_tests", summary } };
  }
  // read_files result is student file content; give_hint result is model-adjacent. Drop.
  return null;
}

function approval(data: unknown): ClientEvent {
  const rec = asRecord(data);
  const commands = extractCommands(rec?.commands);
  return {
    name: "approval",
    data: { allowed: rec?.allowed === true, commands, toolName: stringField(data, "toolName") },
  };
}

function hint(data: unknown): ClientEvent {
  return { name: "hint", data };
}

function hintRejected(data: unknown): ClientEvent {
  const rec = asRecord(data);
  const level = typeof rec?.level === "number" ? rec.level : undefined;
  const reason = stringField(data, "reason");
  return { name: "hint_rejected", data: { level, reason: reasonCategory(reason) } };
}

function status(data: unknown): ClientEvent {
  const rec = asRecord(data);
  // SDK "notice" events carry a free-form message; keep only the notice type.
  if (rec && "noticeType" in rec && "message" in rec) {
    const { message: _message, ...rest } = rec;
    return { name: "status", data: rest };
  }
  return { name: "status", data };
}

function testResults(data: unknown): ClientEvent {
  const r = data as RunResult;
  const { sandboxDir: _sandboxDir, ...rest } = r;
  return { name: "test_results", data: rest };
}

function done(data: unknown): ClientEvent {
  const reason = stringField(data, "reason");
  // `done` also carries the model's final text — never send it.
  return { name: "done", data: { reason: reason || undefined } };
}

/**
 * Map a raw server event to the client-safe event that may be streamed, or
 * `null` when the event type is not on the client allow-list.
 */
export function toClientEvent(name: string, data: unknown): ClientEvent | null {
  switch (name) {
    case "test_results":
      return testResults(data);
    case "tool_call":
      return toolCall(data);
    case "tool_result":
      return toolResult(data);
    case "approval":
      return approval(data);
    case "hint":
      return hint(data);
    case "hint_status":
    case "hint_rejected":
      return hintRejected(data);
    case "status":
      return status(data);
    case "error":
      return friendlyError(data);
    case "done":
      return done(data);
    default:
      // agent_text, reasoning, and anything not explicitly allow-listed.
      return null;
  }
}

